func (t Step) Discriminator() (string, error) {
	var discriminator struct {
		Discriminator string `json:"op"`
	}
	err := json.Unmarshal(t.union, &discriminator)
	return discriminator.Discriminator, err
}

func (t Step) ValueByDiscriminator() (interface{}, error) {
	discriminator, err := t.Discriminator()
	if err != nil {
		return nil, err
	}
	switch discriminator {
	case "autoOrient":
		return t.AsAutoOrientStep()
	case "convert":
		return t.AsConvertStep()
	case "crop":
		return t.AsCropStep()
	case "flip":
		return t.AsFlipStep()
	case "resize":
		return t.AsResizeStep()
	case "rotate":
		return t.AsRotateStep()
	case "watermark":
		return t.AsWatermarkStep()
	default:
		return nil, errors.New("unknown discriminator value: " + discriminator)
	}
}

